import java.util.Scanner;
public class CelsiusToFahrenheit
{
	public static void main (String[] args)
	{
		//Khatwa 1: Taareef al-bayanat alati nahtajha li hadha al-barnamaj
		final int BASE = 32;
		final double CONVERSION_FACTOR = 9.0 / 5;
		//Khatwa 2: Qiraat qimat al-selsiyus al-mudkhala
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil qimat al-selsiyus: ");
		int celsiusTemp = scan.nextInt();
		scan.close();
		//Khatwa 3: Ihsa ma yuwafil li al-Fahrenheit min qimat al-selsiyus
		double fahrenheitTemp = celsiusTemp * CONVERSION_FACTOR + BASE;
		System.out.println("Hararat al-Selsiyus: " + celsiusTemp);
		System.out.println("Ma yuwival bi al-Fahrenheit: " + fahrenheitTemp);
	}
}
